package vn.boardinghub.modules.room;import vn.boardinghub.modules.property.*;import vn.boardinghub.shared.exception.BusinessException;import vn.boardinghub.modules.audit.AuditService;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import java.util.*;
@Service public class RoomService{private final RoomRepository rooms;private final PropertyRepository properties;private final AuditService audit;public RoomService(RoomRepository r,PropertyRepository p,AuditService a){rooms=r;properties=p;audit=a;}public Page<RoomDtos.Response> list(Long propertyId,int page,int size){Pageable pageable=PageRequest.of(page,size,Sort.by("id").descending());Page<Room> result=propertyId==null?rooms.findAll(pageable):rooms.findByPropertyId(propertyId,pageable);return result.map(RoomDtos::from);}@Transactional public RoomDtos.Response create(RoomDtos.Request r){Property p=properties.findById(r.propertyId()).orElseThrow(()->BusinessException.notFound("Property"));Room room=rooms.save(new Room(p,r.code(),r.monthlyRent(),r.capacity(),r.description()));audit.record(actor(),"CREATE","ROOM",room.getId().toString(),room.getCode());return RoomDtos.from(room);}@Transactional public RoomDtos.Response update(Long id,RoomDtos.Request r){Room room=rooms.findById(id).orElseThrow(()->BusinessException.notFound("Room"));if(!room.getProperty().getId().equals(r.propertyId()))throw BusinessException.badRequest("Room property cannot be changed");room.update(r.code(),r.monthlyRent(),r.capacity(),r.description());audit.record(actor(),"UPDATE","ROOM",id.toString(),room.getCode());return RoomDtos.from(room);}private String actor(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}public RoomDtos.Response get(Long id){return RoomDtos.from(rooms.findById(id).orElseThrow(()->BusinessException.notFound("Room")));}@Transactional public void delete(Long id){Room room=rooms.findById(id).orElseThrow(()->BusinessException.notFound("Room"));audit.record(actor(),"DELETE","ROOM",id.toString(),room.getCode());rooms.delete(room);}}
